/* ---------- 셸(대기화면·인트로)용 배경 ---------- */
function bg(c2, w, h, tt) {
  const pc = ctx, pv = camY, pt = time;
  ctx = c2; camY = -H + 70; time = tt || 0;
  c2.save(); c2.scale(w / W, h / H);
  try { drawSky(); drawTrees(); drawGround(); } catch (e) {}
  c2.restore(); ctx = pc; camY = pv; time = pt;
}

/* 인트로: 게임 화면 그대로 (가지·별·제자리에서 통통 뛰는 페리) */
